/// <summary>
/// Extension of class <c>SalesInvoiceController</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceController))]
final class KPMGSalesInvoiceController_Extension
{
}

Method.Source:
    /// <summary>
    /// Retrieves the report header title.
    /// </summary>
    /// <returns>
    /// The report header title.
    /// </returns>
    protected str documentTitle()
    {
        str docTitle = next documentTitle();
        CustLanguageId languageId;
        languageId = this.kpmgGetCustLanguageId();

        if (docTitle == SysLabel::labelId2String(literalStr("@SYS8125"), languageId))
        {
            docTitle = SysLabel::labelId2String(literalStr("@KPMGAddOn:AdjustmentNote"), languageId);
        }
        else if (docTitle == SysLabel::labelId2String(literalStr("@SYS12128"), languageId))
        {
            docTitle = SysLabel::labelId2String(literalStr("@SYS115505"), languageId);
        }

        return docTitle;
    }

    private CustLanguageId kpmgGetCustLanguageId()
    {
        CustLanguageId custLanguageId;

        if (strLen(custInvoiceJour.InvoiceAccount) != 0)
        {
            custLanguageId = CustTable::find(custInvoiceJour.InvoiceAccount).languageId();
        }
        else
        {
            custLanguageId = custInvoiceJour.LanguageId;
        }
        
        return custLanguageId;
    }
